/**
 * Reject a promise by nonce
 */
reject(nonce: string, reason?: any): boolean {
  const promise = this.promises.get(nonce);
  if (!promise) {
    return false;
  }

  if (promise.timeout) {
    clearTimeout(promise.timeout);
  }

  this.promises.delete(nonce);
  promise.reject(reason);
  return true;
}

